class BaseService:
    """Base class for MythTV service endpoints."""

    SERVICE_PATH = ""

    def __init__(self, client: MythTVClient):
        self.client = client

    def _endpoint(self, method: str) -> str:
        return f"/{self.SERVICE_PATH}/{method}"

    def _get(self, method: str, params: dict = None, **kwargs) -> Any:
        return self.client.get(self._endpoint(method), params=params, **kwargs)

    def _post(self, method: str, data: dict = None, json_data: dict = None, params: dict = None, **kwargs) -> Any:
        return self.client.post(self._endpoint(method), data=data, json_data=json_data, params=params, **kwargs)


