# DVR Service
# =============================================================================

class DVRService(BaseService):
    """
    DVR service - Manage recordings, recording rules, and encoder status.
    """
    SERVICE_PATH = "Dvr"

    # --- Recordings ---

    def get_recorded_list(
        self,
        start_index: int = None,
        count: int = None,
        descending: bool = None,
        title_reg_ex: str = None,
        rec_group: str = None,
        storage_group: str = None,
        category: str = None,
        sort: str = None,
    ) -> dict:
        """
        Get list of recorded programs.

        Args:
            start_index: Starting index for pagination.
            count: Number of records to return.
            descending: Sort in descending order.
            title_reg_ex: Regular expression to filter by title.
            rec_group: Recording group filter.
            storage_group: Storage group filter.
            category: Category filter.
            sort: Sort field.

        Returns:
            Dict containing ProgramList.
        """
        params = {
            "StartIndex": start_index,
            "Count": count,
            "Descending": descending,
            "TitleRegEx": title_reg_ex,
            "RecGroup": rec_group,
            "StorageGroup": storage_group,
            "Category": category,
            "Sort": sort,
        }
        return self._get("GetRecordedList", params)

    def get_recorded(
        self,
        recorded_id: int = None,
        chan_id: int = None,
        start_time: datetime = None,
    ) -> dict:
        """
        Get a single recorded program.

        Args:
            recorded_id: Recorded ID.
            chan_id: Channel ID (used with start_time).
            start_time: Recording start time (used with chan_id).

        Returns:
            Dict containing Program.
        """
        params = {
            "RecordedId": recorded_id,
            "ChanId": chan_id,
            "StartTime": start_time,
        }
        return self._get("GetRecorded", params)

    def remove_recorded(
        self,
        recorded_id: int = None,
        chan_id: int = None,
        start_time: datetime = None,
        force_delete: bool = None,
        allow_rerecord: bool = None,
    ) -> dict:
        """
        Delete a recorded program.

        Args:
            recorded_id: Recorded ID.
            chan_id: Channel ID.
            start_time: Recording start time.
            force_delete: Force delete even if in use.
            allow_rerecord: Allow re-recording.

        Returns:
            Bool result.
        """
        params = {
            "RecordedId": recorded_id,
            "ChanId": chan_id,
            "StartTime": start_time,
            "ForceDelete": force_delete,
            "AllowRerecord": allow_rerecord,
        }
        return self._post("RemoveRecorded", data=params)

    def delete_recording(
        self,
        recorded_id: int = None,
        chan_id: int = None,
        start_time: datetime = None,
        force_delete: bool = None,
        allow_rerecord: bool = None,
    ) -> dict:
        """Delete a recording (alias for RemoveRecorded with different backend behavior)."""
        params = {
            "RecordedId": recorded_id,
            "ChanId": chan_id,
            "StartTime": start_time,
            "ForceDelete": force_delete,
            "AllowRerecord": allow_rerecord,
        }
        return self._post("DeleteRecording", data=params)

    def undelete_recording(
        self,
        recorded_id: int = None,
        chan_id: int = None,
        start_time: datetime = None,
    ) -> dict:
        """Undelete a previously deleted recording."""
        params = {
            "RecordedId": recorded_id,
            "ChanId": chan_id,
            "StartTime": start_time,
        }
        return self._post("UnDeleteRecording", data=params)

    def stop_recording(self, recorded_id: int) -> dict:
        """Stop an in-progress recording."""
        return self._post("StopRecording", data={"RecordedId": recorded_id})

    def re_activate_recording(
        self,
        recorded_id: int = None,
        chan_id: int = None,
        start_time: datetime = None,
    ) -> dict:
        """Re-activate a recording."""
        params = {
            "RecordedId": recorded_id,
            "ChanId": chan_id,
            "StartTime": start_time,
        }
        return self._post("ReactivateRecording", data=params)

    def update_recorded_metadata(
        self,
        recorded_id: int,
        auto_expire: bool = None,
        bookmark: int = None,
        damaged: bool = None,
        description: str = None,
        episode: int = None,
        inetref: str = None,
        original_air_date: date = None,
        preserve: bool = None,
        play_group: str = None,
        rec_group: str = None,
        season: int = None,
        stars: float = None,
        sub_title: str = None,
        title: str = None,
        watched: bool = None,
    ) -> dict:
        """Update metadata for a recorded program."""
        params = {
            "RecordedId": recorded_id,
            "AutoExpire": auto_expire,
            "Bookmark": bookmark,
            "Damaged": damaged,
            "Description": description,
            "Episode": episode,
            "Inetref": inetref,
            "OriginalAirDate": original_air_date,
            "Preserve": preserve,
            "PlayGroup": play_group,
            "RecGroup": rec_group,
            "Season": season,
            "Stars": stars,
            "SubTitle": sub_title,
            "Title": title,
            "Watched": watched,
        }
        return self._post("UpdateRecordedMetadata", data=params)

    def set_saved_bookmark(
        self,
        recorded_id: int,
        offset_type: str = None,
        offset: int = None,
    ) -> dict:
        """Set the bookmark position for a recording."""
        params = {
            "RecordedId": recorded_id,
            "OffsetType": offset_type,
            "Offset": offset,
        }
        return self._post("SetSavedBookmark", data=params)

    def get_saved_bookmark(
        self,
        recorded_id: int,
        offset_type: str = None,
    ) -> dict:
        """Get the bookmark position for a recording."""
        params = {
            "RecordedId": recorded_id,
            "OffsetType": offset_type,
        }
        return self._get("GetSavedBookmark", params)

    # --- Recording Rules ---

    def get_record_schedule_list(
        self,
        start_index: int = None,
        count: int = None,
        sort: str = None,
        descending: bool = None,
    ) -> dict:
        """Get list of recording rules/schedules."""
        params = {
            "StartIndex": start_index,
            "Count": count,
            "Sort": sort,
